#!/usr/bin/env node
// Fails when the committed agent definitions differ from a fresh generation
// (#1595).
//
// `agents/agents/{claude-code,gemini-cli}/harness-*.md` are generated by
// `harness generate-agent-definitions` and headed "Do not edit". Nothing
// regenerated or checked them: they sat unchanged from 2026-06-07 while the
// CLI moved through several majors, 11 of 16 drifted per host, and
// `harness-harness-pm.md` never arrived. The doc gates skip generated trees on
// purpose (scripts/check_doc_links.mjs), so every surface stayed green.
// Consumers vendor these files (ADR 0015), so they ran months-old reviewer and
// planner instructions. Same failure, and same remedy, as the Gemini commands
// in #1249 (scripts/gemini-commands-drift.mjs).
//
// How: generate with `--output <scratch>`, which lays the result out as
// `<scratch>/<host>/`, and compare each host's set with the committed one in
// both directions (changed, missing, stale). Unlike generate-slash-commands,
// this generator gives each platform its own subdirectory, so `--output` is
// order-independent here. It runs with cwd = the repo root because it reads
// the repo's own personas as well as the CLI's built-in ones.
//
// Exit codes follow the repo's gate convention (#508):
//   0 = every generated definition is committed, byte for byte, and nothing else
//   1 = DRIFT; the message gives the regenerate command
//   2 = usage error
//   3 = ABSTENTION: the generator is missing, exited non-zero, or emitted zero
//       definitions for any host. A host checked against nothing is not a pass.
//
//   node scripts/agent-definitions-drift.mjs [--root <dir>] [--write]
import { spawnSync } from 'node:child_process';
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { isMain } from './lib/is-main.mjs';

const HOSTS = ['claude-code', 'gemini-cli'];
const OUT_DIR = join('agents', 'agents');
const REGEN = 'node scripts/agent-definitions-drift.mjs --write';

class Abstain extends Error {}

/**
 * Every difference between the generated and committed sets, sorted. A copy of
 * gemini-commands-drift.mjs's diffCommands: importing it made that gate script
 * an imported module and cost it a coupling finding (#1595), more than 12 lines
 * are worth.
 */
function diffSets(generated, committed) {
  const names = [
    ...new Set([...Object.keys(generated), ...Object.keys(committed)]),
  ].sort();
  const out = [];
  for (const name of names) {
    if (!(name in committed)) out.push(`missing: ${name}`);
    else if (!(name in generated)) out.push(`stale: ${name}`);
    else if (generated[name] !== committed[name]) out.push(`changed: ${name}`);
  }
  return out;
}

/** `{ name: contents }` for every .md directly under `dir`. */
function readDefinitions(dir) {
  if (!existsSync(dir)) return {};
  const files = readdirSync(dir).filter((f) => f.endsWith('.md'));
  return Object.fromEntries(
    files.map((f) => [f, readFileSync(join(dir, f), 'utf-8')]),
  );
}

function generatorVersion(bin) {
  const r = spawnSync(bin, ['--version'], { encoding: 'utf-8' });
  return r.error ? 'unknown' : String(r.stdout).trim().split('\n').pop();
}

/** `{ host: { name: contents } }` from a fresh generation into a scratch dir. */
function generate(root, bin, version) {
  const scratch = mkdtempSync(join(tmpdir(), 'agent-definitions-'));
  try {
    const r = spawnSync(
      bin,
      [
        'generate-agent-definitions',
        '--platforms',
        HOSTS.join(','),
        '--output',
        scratch,
      ],
      { cwd: root, encoding: 'utf-8' },
    );
    if (r.error) {
      throw new Abstain(`generator '${bin}' is unavailable (${r.error.code})`);
    }
    if (r.status !== 0) {
      throw new Abstain(
        `generator exited ${r.status}:\n${r.stdout}${r.stderr}`.trimEnd(),
      );
    }
    const out = Object.fromEntries(
      HOSTS.map((h) => [h, readDefinitions(join(scratch, h))]),
    );
    const empty = HOSTS.filter((h) => Object.keys(out[h]).length === 0);
    if (empty.length === HOSTS.length) {
      throw new Abstain(
        `generator (harness ${version}) emitted 0 agent definitions`,
      );
    }
    if (empty.length) {
      throw new Abstain(
        `generator (harness ${version}) emitted no definitions for ${empty.join(', ')}`,
      );
    }
    return out;
  } finally {
    rmSync(scratch, { recursive: true, force: true });
  }
}

/** Replaces a host's committed set with the generated one. */
function writeDefinitions(dir, generated) {
  mkdirSync(dir, { recursive: true });
  for (const name of Object.keys(readDefinitions(dir))) {
    if (!(name in generated)) rmSync(join(dir, name));
  }
  for (const [name, body] of Object.entries(generated)) {
    writeFileSync(join(dir, name), body, 'utf-8');
  }
}

function parseArgs(argv) {
  const opts = { root: join(import.meta.dirname, '..') };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--write') opts.write = true;
    else if (argv[i] === '--root' && argv[i + 1]) opts.root = argv[++i];
    else return null;
  }
  return opts;
}

function run(opts, bin) {
  const version = generatorVersion(bin);
  const generated = generate(opts.root, bin, version);
  const total = HOSTS.reduce((n, h) => n + Object.keys(generated[h]).length, 0);
  if (opts.write) {
    for (const h of HOSTS)
      writeDefinitions(join(opts.root, OUT_DIR, h), generated[h]);
    console.log(`Wrote ${total} agent definitions (harness ${version}).`);
    return 0;
  }
  const drift = HOSTS.flatMap((h) =>
    diffSets(generated[h], readDefinitions(join(opts.root, OUT_DIR, h))).map(
      (line) => line.replace(': ', `: ${h}/`),
    ),
  );
  if (drift.length === 0) {
    console.log(
      `${total} of ${total} agent definitions match a fresh generation ` +
        `across ${HOSTS.join(', ')} (harness ${version}).`,
    );
    return 0;
  }
  console.log(
    `::error::${OUT_DIR} has drifted from a fresh generation ` +
      `(harness ${version}):\n  ${drift.join('\n  ')}\n` +
      `Regenerate with: ${REGEN}`,
  );
  return 1;
}

function main() {
  const opts = parseArgs(process.argv.slice(2));
  if (!opts) {
    console.error(
      'usage: agent-definitions-drift.mjs [--root <dir>] [--write]',
    );
    process.exit(2);
  }
  const bin = process.env.HARNESS_BIN || 'harness';
  try {
    process.exit(run(opts, bin));
  } catch (err) {
    if (!(err instanceof Abstain)) throw err;
    console.log(`ABSTAINED: ${err.message}. Nothing was checked.`);
    process.exit(3);
  }
}

if (isMain(import.meta.url)) {
  main();
}
